(function(){const c=$('#sky'),x=c.getContext('2d');let W,H,pts=[];
  const blobs=[{h:'47,134,246',r:.5,sx:.00011,sy:.00013,px:.2,py:.15},{h:'236,72,153',r:.45,sx:.00009,sy:.00012,px:.85,py:.2},{h:'157,124,242',r:.4,sx:.00013,sy:.00008,px:.6,py:.8}];
  function size(){const d=Math.min(2,devicePixelRatio||1);W=innerWidth;H=innerHeight;c.width=W*d;c.height=H*d;x.setTransform(d,0,0,d,0,0);pts=Array.from({length:Math.round(Math.min(60,W*H/24000))},()=>({x:Math.random()*W,y:Math.random()*H,vx:rnd(-.12,.12),vy:rnd(-.12,.12),r:rnd(.8,1.8)}))}
  function frame(t){const dark=root.getAttribute('data-theme')==='dark',ba=dark?.18:.09,la=dark?.1:.12,pc=dark?'rgba(200,215,255,.6)':'rgba(47,134,246,.35)';x.clearRect(0,0,W,H);
    blobs.forEach((b,i)=>{const cx=W*(b.px+.1*Math.sin(t*b.sx+i)),cy=H*(b.py+.1*Math.cos(t*b.sy+i)),R=Math.max(W,H)*b.r;const g=x.createRadialGradient(cx,cy,0,cx,cy,R);g.addColorStop(0,`rgba(${b.h},${ba})`);g.addColorStop(1,`rgba(${b.h},0)`);x.fillStyle=g;x.fillRect(0,0,W,H)});
    for(const p of pts){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1}
    for(let i=0;i<pts.length;i++){const a=pts[i];for(let j=i+1;j<pts.length;j++){const b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<120){x.strokeStyle=`rgba(${dark?'169,214,255':'47,134,246'},${la*(1-d/120)})`;x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke()}}x.fillStyle=pc;x.beginPath();x.arc(a.x,a.y,a.r,0,7);x.fill()}
    if(!reduce&&!document.hidden)requestAnimationFrame(frame)}
  size();addEventListener('resize',size);requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!reduce)requestAnimationFrame(frame)})})();
addEventListener('pointermove',e=>{const o=$('.orb');if(!o||$('#landing').hidden)return;const r=o.getBoundingClientRect();const dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy)||1,k=Math.min(7,d/40);$('#eyes').style.transform=`translate(${dx/d*k}px,${dy/d*k}px)`},{passive:true});

