let vt=0,playing=false,last=0,cur=-1;const fmt=ms=>{const s=Math.floor(ms/1000);return Math.floor(s/60)+':'+pad(s%60)};
function speak(t){try{if(!$('#narrate').checked||!window.speechSynthesis)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=1.05;u.lang='en-IN';speechSynthesis.speak(u)}catch(e){}}
function showScene(i,f){if(i===cur&&!f)return;cur=i;scenes.forEach((s,j)=>{s.classList.remove('active');if(j===i){void s.offsetWidth;s.classList.add('active')}});$('#caption').innerHTML=`<b>${pad(i+1)}</b>${scenes[i].dataset.cap}`;$$('.chap').forEach((c,j)=>c.classList.toggle('on',j===i));if(playing)speak(scenes[i].dataset.cap)}
function setPlay(p){playing=p;$('#screen').classList.toggle('paused',!p);$('#bigplay').hidden=p;$('#playIco').innerHTML=p?'<path d="M6 5h4v14H6zM14 5h4v14h-4z"/>':'<path d="M8 5v14l11-7z"/>';if(p){if(vt>=TOTAL){vt=0;cur=-1}last=performance.now();showScene(Math.floor(vt/SMS),true);requestAnimationFrame(vtick)}else{try{speechSynthesis.cancel()}catch(e){}}}
function vtick(now){if(!playing)return;vt+=now-last;last=now;if(vt>=TOTAL){vt=TOTAL;vdraw();setPlay(false);return}showScene(Math.floor(vt/SMS));vdraw();requestAnimationFrame(vtick)}
function vdraw(){$('#progFill').style.width=(vt/TOTAL*100)+'%';$('#time').textContent=fmt(vt)+' / '+fmt(TOTAL)}
function seek(ms){vt=Math.max(0,Math.min(TOTAL-1,ms));showScene(Math.floor(vt/SMS),true);vdraw()}
$('#bigplay').onclick=()=>setPlay(true);$('#playBtn').onclick=()=>setPlay(!playing);$('#restartBtn').onclick=()=>{seek(0);setPlay(true)};
