let atsSel=1;const atsName=()=>ATS[atsSel][0];
const syncLog=[['in','Pulled 6 new applications · REQ-2318'],['out','Wrote 12 scores · REQ-2291'],['out','Moved 4 candidates to Interview'],['in','Webhook: offer accepted · Kavya Desai']];
function renderSync(){$('#sync').innerHTML=`<div style="display:flex;justify-content:space-between;font-size:.78rem;font-weight:600"><span>Two-way sync · ${atsName()}</span><span class="mono" style="color:var(--good);font-weight:400">● live</span></div>`+syncLog.slice(0,5).map(([d,t])=>`<div class="sync-row"><span class="dir ${d}">${d==='in'?'ATS → AJ':'AJ → ATS'}</span><span>${esc(t)}</span><time>${clock()}</time></div>`).join('')}
function renderAts(){$('#atsList').innerHTML=ATS.map((a,i)=>`<button class="ats ${i===atsSel?'on':''}" data-i="${i}">${a[0]}<small>${a[1]}</small></button>`).join('');const slug=atsName().toLowerCase().replace(/\s+/g,'_');$('#cfgProvider').textContent=slug;$('#atsName').textContent=slug;$('#wsAts').innerHTML=ATS.map((a,i)=>`<option value="${i}" ${i===atsSel?'selected':''}>${a[0]}</option>`).join('');$('#conAts').textContent=atsName();renderSync();if(window.__hub)window.__hub()}
$('#atsList').onclick=e=>{const b=e.target.closest('.ats');if(b){atsSel=+b.dataset.i;syncLog.unshift(['in',`Connected to ${atsName()} · fields mapped`]);renderAts()}};
$('#wsAts').onchange=e=>{atsSel=+e.target.value;renderAts();toast('Switched to '+atsName()+' (sample connection)')};renderAts();

/* ROI */
function roi(){const rec=+$('#rRec').value,req=+$('#rReq').value,hrs=+$('#rHrs').value,cost=+$('#rCost').value,ttf=+$('#rTtf').value;$('#oRec').textContent=rec;$('#oReq').textContent=req;$('#oHrs').textContent=hrs+' h';$('#oCost').textContent=inr(cost);$('#oTtf').textContent=ttf+' d';const s=req*hrs*.7;$('#vHrs').textContent=Math.round(s).toLocaleString('en-IN');$('#vSave').textContent=inr(s*12*cost);$('#vFte').textContent=(s/160).toFixed(1);$('#vTtf').textContent=Math.round(ttf*.55);$('#vPer').textContent=(s/rec/4.33).toFixed(1)}
$$('#roi input').forEach(i=>i.addEventListener('input',roi));roi();

/* ================= REPORT ================= */
function repData(p){const m={m:1,q:1.4,lq:3}[p]||1;const label={m:'Sep 12 – Oct 12, 2026',q:'Oct 1 – Oct 12, 2026 (QTD)',lq:'Jul 1 – Sep 30, 2026'}[p];const hires=Math.round(42*m),offers=Math.round(hires*1.22),intv=Math.round(offers*4.1),scr=Math.round(intv*3.4),app=Math.round(scr*2.6);
  return{label,m,hires,offers,intv,scr,app,ttf:23.4,ttfPrev:31.8,oar:Math.round(hires/offers*100),cph:61500,cphPrev:84200,sla:91,src:[['ATS silver medallist',.18,.31,8200],['Referral',.12,.24,42000],['Naukri',.34,.21,58000],['LinkedIn',.26,.17,96000],['Career site',.10,.07,21000]],ttfRole:[['React Developer',18],['Data Engineer',21],['Senior Java Developer',24],['QA Lead',29],['Salesforce Architect',37],['Staff SRE',44]],team:[['Ritika S.',14,9,21,4.6],['Mohit A.',12,7,24,4.4],['Farah K.',11,8,19,4.7],['Sanjay P.',9,5,31,4.1],['Leena D.',8,6,22,4.5]],agent:{tasks:Math.round(18240*m),hrs:Math.round(1310*m),inr:Math.round(1310*m*850),auto:72}}}
function hbars(rows,max,fv,col){return`<div class="hbars">${rows.map(([l,v],i)=>`<div class="hb"><span>${esc(l)}</span><div class="track"><i style="width:${v/max*100}%;background:${col?col(i,v):'var(--grad)'}"></i></div><span class="v">${fv(v)}</span></div>`).join('')}</div>`}
function weekBars(d){const w=d.m>=3?13:d.m>1?6:5;const vals=Array.from({length:w},(_,i)=>Math.max(2,Math.round(d.hires/w*(0.7+i/w*.6)+rnd(-1.5,1.5))));const max=Math.max(...vals),W=520,H=150,pl=28,pb=22,bw=(W-pl-10)/w;let g='';
  [0,.5,1].forEach(k=>{const yy=H-pb-(H-pb-10)*k;g+=`<line x1="${pl}" x2="${W-6}" y1="${yy}" y2="${yy}" class="sv-grid"/><text x="${pl-6}" y="${yy+3}" text-anchor="end" font-size="9" class="sv-dim" font-family="IBM Plex Mono,monospace">${Math.round(max*k)}</text>`});
  vals.forEach((v,i)=>{const h=(H-pb-10)*v/max,x=pl+i*bw+bw*.18;g+=`<rect x="${x}" y="${H-pb-h}" width="${bw*.64}" height="${h}" rx="3" fill="url(#gGradV)"/>`;if(i===0||i===w-1||(w>6&&i===Math.floor(w/2)))g+=`<text x="${x+bw*.32}" y="${H-6}" text-anchor="middle" font-size="9" class="sv-dim" font-family="IBM Plex Mono,monospace">W${i+1}</text>`});
  return`<div style="overflow-x:auto"><svg viewBox="0 0 ${W} ${H}" width="100%" style="min-width:360px" role="img" aria-label="Hires per week">${g}</svg></div>`}
function tiles(arr){return`<div class="tiles">${arr.map(([l,n,d])=>`<div class="tile"><div class="l">${l}</div><div class="n">${n}</div><div class="d up">${d}</div></div>`).join('')}</div>`}
function repSection(k,d){switch(k){
 case 'exec':return`${tiles([['Hires',d.hires,'+18% vs prior period'],['Time-to-fill',d.ttf+'d','−'+(d.ttfPrev-d.ttf).toFixed(1)+'d vs prior'],['Offer acceptance',d.oar+'%','+9 pts'],['Cost per hire',cr(d.cph),'−27% vs prior']])}<p class="c">The team closed ${d.hires} hires in this period, ahead of plan. Time-to-fill fell to ${d.ttf} days as the Screener and Scheduler agents removed most manual screening and calendar work. Two senior requisitions, Staff SRE in Noida and Salesforce Architect in Pune, are behind and need a decision on scope or budget this week.</p>${weekBars(d)}`;
 case 'funnel':{const f=[['Applied',d.app],['Screened',d.scr],['Interviewed',d.intv],['Offered',d.offers],['Joined',d.hires]];return`${hbars(f,d.app,v=>v.toLocaleString('en-IN'),i=>STGC[i])}<div class="tbl"><table><thead><tr><th>Stage</th><th class="r">Count</th><th class="r">Conversion</th><th class="r">Benchmark</th></tr></thead><tbody>${f.map(([l,v],i)=>`<tr><td>${l}</td><td class="r">${v.toLocaleString('en-IN')}</td><td class="r">${i?Math.round(v/f[i-1][1]*100)+'%':'—'}</td><td class="r">${['—','35%','25%','22%','80%'][i]}</td></tr>`).join('')}</tbody></table></div><p class="c">Screen-to-interview conversion is above benchmark because the shortlist reaching hiring managers is smaller and better matched. Offer-to-join is the stage to watch.</p>`}
 case 'source':return`<div class="tbl"><table><thead><tr><th>Source</th><th class="r">Share of applicants</th><th class="r">Share of hires</th><th class="r">Cost per hire</th><th>Verdict</th></tr></thead><tbody>${d.src.map(([s,a,h,c])=>`<tr><td><span class="health"><i style="background:${SRCC[s]}"></i>${s}</span></td><td class="r">${Math.round(a*100)}%</td><td class="r">${Math.round(h*100)}%</td><td class="r">${inr(c)}</td><td><span class="tag ${h>a?'g':h>a*.7?'w':'r'}">${h>a?'Over-delivers':h>a*.7?'In line':'Under-delivers'}</span></td></tr>`).join('')}</tbody></table></div><p class="c">ATS silver medallists produce 31% of hires from 18% of applicants at the lowest cost. LinkedIn is the most expensive channel per hire. Shift sourcing effort towards the ATS and referrals first.</p>`;
 case 'speed':return`${tiles([['Avg time-to-fill',d.ttf+'d','−8.4d'],['Time to first screen','3.1h','was 2.6 days'],['Interview SLA met',d.sla+'%','+14 pts'],['Feedback turnaround','1.8d','target 2d']])}${hbars(d.ttfRole,50,v=>v+'d',(i,v)=>v>35?'var(--bad)':v>26?'#E39A12':'var(--good)')}<p class="c">Speed is driven by two senior roles. Excluding them, average time-to-fill is under 23 days.</p>`;
 case 'cost':{const tot=d.cph*d.hires;return`${tiles([['Total hiring cost',cr(tot),'this period'],['Cost per hire',cr(d.cph),'was '+cr(d.cphPrev)],['Agency spend',cr(tot*.21),'−34%'],['Saved by AJ',cr(d.agent.inr),'recruiter time']])}${hbars([['Job boards',.34],['Agencies',.21],['Recruiter time',.28],['Assessments',.09],['Employer branding',.08]],.4,v=>Math.round(v*100)+'%')}<p class="c">Agency spend dropped by a third as more roles were filled from the ATS and referrals.</p>`}
 case 'roles':return`<div class="tbl"><table><thead><tr><th>Requisition</th><th>Location</th><th class="r">Openings</th><th class="r">Pipeline</th><th class="r">Days open</th><th>Status</th></tr></thead><tbody>${REQS.map(r=>{const p=POOL.filter(c=>c.req===r.id).length,hc={good:['var(--good)','On track'],warn:['var(--warn)','Watch'],bad:['var(--bad)','At risk']}[r.health];return`<tr><td><b style="font-weight:600">${r.id}</b> · ${esc(r.role)}</td><td>${esc(r.city)}</td><td class="r">${r.open}</td><td class="r">${p}</td><td class="r">${({good:18,warn:31,bad:42})[r.health]}</td><td><span class="health"><i style="background:${hc[0]}"></i>${hc[1]}</span></td></tr>`}).join('')}</tbody></table></div>`;
 case 'team':return`<div class="tbl"><table><thead><tr><th>Recruiter</th><th class="r">Reqs owned</th><th class="r">Hires</th><th class="r">Avg TTF</th><th class="r">HM rating</th></tr></thead><tbody>${d.team.map(([n,r,h,t,s])=>`<tr><td>${n}</td><td class="r">${r}</td><td class="r">${Math.round(h*d.m)}</td><td class="r">${t}d</td><td class="r">${s.toFixed(1)} / 5</td></tr>`).join('')}</tbody></table></div><p class="c">Average load is 10.8 requisitions per recruiter, up from 7.2 before AJ, with no drop in hiring-manager rating.</p>`;
 case 'agent':return`${tiles([['Agent tasks',d.agent.tasks.toLocaleString('en-IN'),'this period'],['Hours saved',d.agent.hrs.toLocaleString('en-IN'),'≈ '+(d.agent.hrs/160).toFixed(1)+' FTE months'],['Value of time saved',cr(d.agent.inr),'at ₹850/hour'],['Fully autonomous',d.agent.auto+'%','rest approved by people']])}${hbars(AGENTS.map(a=>[a.nm,Math.round(a.done*d.m*12)]),Math.max(...AGENTS.map(a=>a.done*d.m*12)),v=>v.toLocaleString('en-IN'),i=>AGENTS[i].c)}<p class="c">Every agent action is logged with its reason. Approval rate on agent suggestions is 96%, and recruiters overrode 4% of screening scores.</p>`;
 case 'recs':return`<ol class="recs"><li><div><b>Widen the Staff SRE search</b><span>Add Gurugram, Pune and remote candidates. The Noida pool for Kubernetes plus GCP is too thin.</span></div><span class="tag r">High</span></li><li><div><b>Revisit the Salesforce Architect band</b><span>The offer is 18% under market median. Two offers were declined on CTC.</span></div><span class="tag r">High</span></li><li><div><b>Move budget from LinkedIn to referrals</b><span>Referrals hire at less than half the cost per hire.</span></div><span class="tag w">Medium</span></li><li><div><b>Add a second QA panelist</b><span>Feedback on QA Lead takes 5.2 days and is the main delay.</span></div><span class="tag w">Medium</span></li><li><div><b>Set the Scheduler to Autonomous</b><span>98% of its bookings were approved without change last month.</span></div><span class="tag g">Quick win</span></li></ol>`}}
let repPeriod='m',RD=repData('m');
function renderReport(){RD=repData(repPeriod);const d=RD;$('#repToc').innerHTML=RCATS.map(([k,t],i)=>`<button data-k="${k}"><span>${pad(i+1)}</span>${t}</button>`).join('');
  $('#doc').innerHTML=`<div class="doc-cover glass"><span class="cat"><b>Insights</b><i></i>Talent Acquisition performance report</span><h2>Hiring is faster and cheaper; two senior roles need attention.</h2><div class="doc-meta"><div><b>Period</b>${d.label}</div><div><b>Scope</b>All business units · India</div><div><b>Source</b>${atsName()} via AJ</div><div><b>Prepared by</b>Analyst agent · ${clock()} IST</div></div></div>`+RCATS.map(([k,t,c],i)=>`<section class="rsec glass" id="r-${k}"><div class="rsec-h"><span class="no">${pad(i+1)}</span><h3>${t}</h3><span class="catl">${c}</span></div>${repSection(k,d)}</section>`).join('')}
$('#repToc').onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('#repToc button').forEach(x=>x.classList.toggle('on',x===b));$('#r-'+b.dataset.k).scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'})};
$('#repPeriod').onchange=e=>{repPeriod=e.target.value;renderReport();toast('Report updated for '+RD.label)};
$('#repRegen').onclick=async()=>{const b=$('#repRegen');b.disabled=true;b.innerHTML='Analysing<span class="thinking"><i></i><i></i><i></i></span>';await sleep(1300);renderReport();b.disabled=false;b.textContent='Regenerate';pushFeed('analyst','Regenerated TA report · '+RD.label);toast('Report regenerated from latest ATS data')};
const execText=()=>{const d=RD;return`TA performance · ${d.label}\n\n• Hires: ${d.hires} (+18% vs prior period)\n• Time-to-fill: ${d.ttf} days (down from ${d.ttfPrev})\n• Offer acceptance: ${d.oar}%\n• Cost per hire: ${inr(d.cph)} (down 27%)\n• AJ saved ${d.agent.hrs.toLocaleString('en-IN')} recruiter hours (${cr(d.agent.inr)})\n\nNeeds attention: Staff SRE Noida (thin pipeline), Salesforce Architect Pune (offer below market).`};
function copyText(t,okMsg){try{navigator.clipboard.writeText(t).then(()=>toast(okMsg),()=>toast('Copy blocked here. Select the text instead.',false))}catch(e){toast('Copy blocked here. Select the text instead.',false)}}
$('#repCopy').onclick=()=>copyText(execText(),'Executive summary copied');
let rpSel='exec';function renderRp(){const d=repData('m');$('#rpCats').innerHTML=RCATS.map(([k,t],i)=>`<button data-k="${k}" class="${k===rpSel?'on':''}"><span>${pad(i+1)}</span>${t}</button>`).join('');const i=RCATS.findIndex(r=>r[0]===rpSel);$('#rpBody').innerHTML=`<div class="rsec-h"><span class="no">${pad(i+1)}</span><h3>${RCATS[i][1]}</h3><span class="catl">${RCATS[i][2]}</span></div>${repSection(rpSel,d)}`}
$('#rpCats').onclick=e=>{const b=e.target.closest('button');if(b){rpSel=b.dataset.k;renderRp()}};renderRp();

/* ================= WORKSPACE ================= */
function renderTab(){if(tab==='atscon')renderAtc();if(tab==='pipeline')renderBoard();if(tab==='analytics')renderAnalytics();if(tab==='agents')renderAgents();if(tab==='command')renderRail();if(tab==='reports'&&!$('#doc').children.length)renderReport()}
const FEED=[];const feedHtml=f=>`<div><time>${f.t}</time><span class="ag" style="background:${AG[f.ag]?.c||'#858CB0'}">${AG[f.ag]?.nm||'AJ'}</span><span>${esc(f.x)}</span></div>`;
function pushFeed(ag,x){FEED.unshift({t:clock(),ag,x});if(FEED.length>40)FEED.pop();if(view!=='ws')return;if(tab==='command'){$('#railFeed').innerHTML=FEED.slice(0,12).map(feedHtml).join('');$('#railCount').textContent=FEED.length+' events'}if(tab==='analytics')$('#anFeed').innerHTML=FEED.slice(0,16).map(feedHtml).join('')}
['Synced 34 stage updates to ATS','Flagged REQ-1987: fewer than 5 qualified','Booked Priya Kulkarni · Tue 11:30','Found 64 profiles for REQ-2318'].forEach((x,i)=>pushFeed(['tara','analyst','scheduler','sourcer'][i],x));
function renderRail(){$('#railAgents').innerHTML=AGENTS.map(a=>`<div class="agent-mini"><span class="av" style="background:${a.c}">${a.ic}</span><div><b style="font-weight:600">${a.nm}</b><small>${esc(a.now)}</small></div><span class="tag ${a.mode==='suggest'?'w':a.mode==='approve'?'p':'g'}">${a.mode==='auto'?'Auto':a.mode==='approve'?'Approve':'Suggest'}</span></div>`).join('');$('#railFeed').innerHTML=FEED.slice(0,12).map(feedHtml).join('');$('#railCount').textContent=FEED.length+' events'}

function renderApprCount(){const n=APPROVALS.length;$('#apprCnt').textContent=n;$('#dockBadge').textContent=n;$('#dockBadge').hidden=!n;$('#bAppr').textContent=n;$('#bAppr').hidden=!n}
function addApproval(ag,x,kind){APPROVALS.unshift({id:++apprId,ag,t:clock(),x,kind});renderApprCount();if(overlayKind==='appr')openApprovals()}renderApprCount();
let overlayKind=null;function closeOverlay(){$('#overlay').innerHTML='';overlayKind=null}
function drawer(html,kind){overlayKind=kind;$('#overlay').innerHTML=`<div class="scrim" data-close></div><aside class="drawer" role="dialog" aria-modal="true"><button class="btn btn-ghost btn-sm x" data-close aria-label="Close">✕</button>${html}</aside>`}
$('#overlay').addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeOverlay()});
function approve(i){award('m_approve');const a=APPROVALS.splice(i,1)[0];toast('Approved: '+a.kind);pushFeed(a.ag,'Approved · '+a.x);syncLog.unshift(['out',a.kind+' executed']);renderSync();renderApprCount()}
function openApprovals(){drawer(`<div><span class="cat"><b>Control</b><i></i>Approval queue</span><h3 style="margin-top:8px">${APPROVALS.length} waiting for you</h3><p style="color:var(--muted);font-size:.86rem;margin-top:4px">Actions your guardrails hold until you sign off.</p></div><div class="res-actions">${APPROVALS.length?'<button class="btn btn-primary btn-sm" data-all>Approve all</button>':''}${dlBtns('appr')}</div><div class="appr">${APPROVALS.map(a=>`<div class="appr-item" data-id="${a.id}"><div class="h"><span class="ag" style="background:${AG[a.ag].c}">${AG[a.ag].nm}</span><span class="tag p">${a.kind}</span><time>${a.t}</time></div><p>${esc(a.x)}</p><div class="res-actions"><button class="btn btn-primary btn-sm" data-ok>Approve</button><button class="btn btn-ghost btn-sm" data-no>Decline</button></div></div>`).join('')||'<div class="empty"><b>All clear</b>Nothing is waiting for approval.</div>'}</div>`,'appr');
  $('.drawer').onclick=e=>{if(e.target.closest('[data-all]')){if(APPROVALS.length)award('m_approve');const n=APPROVALS.length;APPROVALS.splice(0);renderApprCount();openApprovals();toast(n+' actions approved');pushFeed('tara',n+' queued actions approved');return}const it=e.target.closest('.appr-item');if(!it)return;const i=APPROVALS.findIndex(a=>a.id===+it.dataset.id);if(i<0)return;
    if(e.target.closest('[data-ok]'))approve(i);else if(e.target.closest('[data-no]')){const a=APPROVALS.splice(i,1)[0];toast('Declined',false);pushFeed(a.ag,'Declined · '+a.kind);renderApprCount()}else return;openApprovals()}}

function radar(br){const cx=150,cy=130,R=92,n=AXES.length,pt=(i,v)=>{const a=-Math.PI/2+i/n*Math.PI*2;return[cx+Math.cos(a)*R*v,cy+Math.sin(a)*R*v]};let g='';[.25,.5,.75,1].forEach(k=>{g+=`<polygon points="${AXES.map((_,i)=>pt(i,k).join(',')).join(' ')}" fill="none" class="sv-grid"/>`});
  AXES.forEach((ax,i)=>{const [x,y]=pt(i,1),[lx,ly]=pt(i,1.22);g+=`<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" class="sv-grid"/><text x="${lx}" y="${ly+4}" text-anchor="middle" font-size="11" class="sv-mut" font-family="IBM Plex Sans,sans-serif">${ax} <tspan class="sv-txt" font-weight="600">${br[i]}</tspan></text>`});
  return`<svg class="radar" viewBox="0 0 300 260" role="img" aria-label="Score breakdown">${g}<polygon points="${br.map((v,i)=>pt(i,v/100).join(',')).join(' ')}" fill="url(#gGrad)" fill-opacity=".28" stroke="url(#gGrad)" stroke-width="2"/>${br.map((v,i)=>{const [x,y]=pt(i,v/100);return`<circle cx="${x}" cy="${y}" r="3.5" fill="#EC4899"/>`}).join('')}</svg>`}
function openCand(id){const c=byId(id);if(!c)return;award('m_card');const order=c.br.map((v,i)=>[v,i]).sort((a,b)=>b[0]-a[0]),si=STG.indexOf(c.stage);
  const why=c.why||[`Strong ${AXES[order[0][1]].toLowerCase()} fit (${order[0][0]}) for ${c.role}`,`${c.exp} years experience · ${c.sk.join(', ')} confirmed`,`Good ${AXES[order[1][1]].toLowerCase()} signal (${order[1][0]})`];
  const neg=c.miss&&c.miss.length?`Missing: ${c.miss.join(', ')}. Probe in the interview.`:order[5][0]<72?`Weaker on ${AXES[order[5][1]].toLowerCase()} (${order[5][0]}). Worth probing.`:null;
  drawer(`<div class="d-head"><span class="d-av">${esc(c.nm.split(' ').map(w=>w[0]).join('').slice(0,2))}</span><div><h3>${esc(c.nm)}</h3><p>${esc(c.role)} · ${c.req} · ${esc(c.city)}</p></div></div><div class="d-score"><div class="big gt">${c.sc}</div><div><span class="tag" style="background:${STGC[si]}22;color:${STGC[si]}">${c.stage}</span><p style="color:var(--muted);font-size:.82rem;margin-top:4px">Match score · bias masking on</p></div></div>${radar(c.br)}
  <div><div class="lbl">Why this score</div><ul class="why">${why.map(w=>`<li>${esc(w)}</li>`).join('')}${neg?`<li class="neg">${esc(neg)}</li>`:''}</ul></div><div class="facts"><div><span>Notice</span>${c.np?c.np+' days':'Immediate'}</div><div><span>Expected CTC</span>₹${c.ctc} LPA</div><div><span>Source</span>${esc(c.src)}</div><div><span>Experience</span>${c.exp} yrs</div></div>
  <div><div class="lbl">Agent timeline</div><div class="tl">${c.ev.slice().reverse().map(e=>`<div><time>${e.t}</time>${esc(e.x)}</div>`).join('')||'<div>No events yet</div>'}</div></div><div class="res-actions">${si<4?`<button class="btn btn-primary btn-sm" data-next>Move to ${STG[si+1]}</button>`:''}<button class="btn btn-ghost btn-sm" data-msg>Draft outreach</button>${dlBtns('cand:'+c.id)}${AI.on?'<button class="btn btn-ghost btn-sm" data-aimsg>✦ Write with Live AI</button>':''}</div><div id="dDraft"></div>`,'cand');
  $('.drawer').onclick=e=>{if(e.target.closest('[data-aimsg]')){aiOutreach(c);return}if(e.target.closest('[data-next]')){moveCand(c,STG[si+1],'You');openCand(id);toast(`${c.nm} moved to ${c.stage} · synced to ${atsName()}`)}if(e.target.closest('[data-msg]'))$('#dDraft').innerHTML=`<div class="draft">${esc(outreach(c))}</div><div class="res-actions" style="margin-top:8px"><button class="btn btn-primary btn-sm" data-queue>Send for approval</button></div>`;if(e.target.closest('[data-queue]')){addApproval('sourcer',`Send outreach to ${c.nm} (${c.req})`,'Outreach');toast('Added to approval queue');$('#dDraft').innerHTML=''}}}
