async function runSteps(container,steps){const log=document.createElement('div');log.className='log';container.appendChild(log);for(const [ag,tool,txt] of steps){const a=AG[ag]||{c:'#858CB0',nm:'AJ'};const row=document.createElement('div');row.innerHTML=`<span class="st"><span class="spin">◌</span></span><span class="ag" style="background:${a.c}">${a.nm}</span><span class="tool">${tool}</span><span class="txt">${esc(txt)}</span>`;log.appendChild(row);row.scrollIntoView({block:'nearest'});if(AG[ag])AG[ag].now=tool+' · '+txt;if(view==='ws'&&tab==='command')renderRail();await sleep(reduce?60:rnd(480,900));const st=row.querySelector('.st');st.textContent='✓';st.classList.add('done');pushFeed(ag,txt);if(AG[ag]){AG[ag].done++;AG[ag].hist[19]++}}}
