function candTable(list){return`<div class="tbl"><table><thead><tr><th></th><th>Candidate</th><th>Match</th><th>Key skills</th><th class="r">Exp</th><th>Notice</th><th>Source</th></tr></thead><tbody>${list.map(c=>`<tr class="click" data-c="${c.id}"><td><input type="checkbox" checked aria-label="Select ${esc(c.nm)}"></td><td><b style="font-weight:600">${esc(c.nm)}</b></td><td><span class="score">${c.sc}<i><b style="width:${c.sc}%"></b></i></span></td><td>${c.sk.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}${(c.miss||[]).map(s=>`<span class="tag miss">${esc(s)}</span>`).join('')}</td><td class="r">${c.exp}y</td><td><span class="tag ${c.np<=30?'g':'w'}">${c.np?c.np+'d':'Now'}</span></td><td style="color:var(--muted)">${esc(c.src)}</td></tr>`).join('')}</tbody></table></div>`}
