  const sc=Math.round(100*(.5*sSkill+.2*sExp+.15*sNp+.15*sLoc));const br=[Math.round(sSkill*100),Math.round(sExp*100),Math.round(rnd(68,92)),Math.round(sNp*100),Math.round(sLoc*100),Math.round(rnd(65,95))];
