/* pipeline */
function renderReqFilter(){const v=$('#reqFilter').value||'all';$('#reqFilter').innerHTML=`<option value="all">All requisitions</option>`+REQS.map(r=>`<option value="${r.id}">${r.id} · ${esc(r.role)}</option>`).join('');$('#reqFilter').value=REQS.some(r=>r.id===v)?v:'all'}
renderReqFilter();$('#reqFilter').onchange=renderBoard;let dragging=null;const justMoved=new Set();
function renderBoard(){if(dragging)return;const f=$('#reqFilter').value,list=POOL.filter(c=>f==='all'||c.req===f);$('#board').innerHTML=STG.map((s,i)=>{const cs=list.filter(c=>c.stage===s).sort((a,b)=>b.sc-a.sc),sh=cs.slice(0,14);return`<div class="col" data-s="${s}"><div class="col-h"><span><i style="background:${STGC[i]}"></i>${s}</span><span>${cs.length}</span></div>${sh.map(c=>`<button class="kcard ${justMoved.has(c.id)?'moved':''}" draggable="true" data-c="${c.id}"><div class="r1"><b>${esc(c.nm)}</b><span class="sc ${c.sc>=85?'':c.sc>=75?'m':'l'}">${c.sc}</span></div><div class="meta">${c.req} · ${esc(c.city)}</div><div>${c.sk.slice(0,2).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div></button>`).join('')}${cs.length>sh.length?`<div class="more">+${cs.length-sh.length} more</div>`:''}</div>`}).join('');justMoved.clear()}
const board=$('#board');
board.addEventListener('dragstart',e=>{const k=e.target.closest('.kcard');if(!k)return;dragging=k.dataset.c;k.style.opacity=.4;e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',dragging)}catch(_){}});
board.addEventListener('dragend',()=>{dragging=null;renderBoard()});
board.addEventListener('dragover',e=>{const col=e.target.closest('.col');if(!col)return;e.preventDefault();$$('.col').forEach(c=>c.classList.toggle('over',c===col))});
board.addEventListener('drop',e=>{const col=e.target.closest('.col');if(!col||!dragging)return;e.preventDefault();const c=byId(dragging),s=col.dataset.s;if(c&&c.stage!==s){moveCand(c,s,'You');justMoved.add(c.id);toast(`${c.nm} → ${s} · synced to ${atsName()}`);pushFeed('tara',`${c.nm} moved to ${s}`)}dragging=null;renderBoard()});
board.addEventListener('click',e=>{const k=e.target.closest('.kcard');if(k)openCand(k.dataset.c)});

/* analytics */
const BASE=[1180,420,104,44,9];
function renderAnalytics(){const cum=STG.map((s,i)=>POOL.filter(c=>STG.indexOf(c.stage)>=i).length+BASE[i]);$('#funnel').innerHTML=cum.map((v,i)=>`<div class="frow"><span class="lb">${STG[i]}</span><div><div class="b" style="width:${v/cum[0]*100}%;background:${STGC[i]}"></div></div><span class="v">${v.toLocaleString('en-IN')}</span><span class="c">${i?Math.round(v/cum[i-1]*100)+'%':''}</span></div>`).join('');
  const m={};POOL.forEach(c=>m[c.src]=(m[c.src]||0)+1);const tot=POOL.length;let a0=-Math.PI/2,arcs='';Object.entries(m).forEach(([k,v])=>{const a1=a0+v/tot*Math.PI*2-.02,r=48;arcs+=`<path d="M${60+r*Math.cos(a0)} ${60+r*Math.sin(a0)} A${r} ${r} 0 ${a1-a0>Math.PI?1:0} 1 ${60+r*Math.cos(a1)} ${60+r*Math.sin(a1)}" stroke="${SRCC[k]||'#858CB0'}" stroke-width="16" fill="none"/>`;a0=a1+.02});
  $('#donut').innerHTML=arcs+`<text x="60" y="60" text-anchor="middle" font-family="Chakra Petch,sans-serif" font-size="20" font-weight="700" class="sv-txt">${tot}</text><text x="60" y="75" text-anchor="middle" font-size="9" class="sv-dim" font-family="IBM Plex Sans,sans-serif">in pipeline</text>`;
  $('#legend').innerHTML=Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div><i style="background:${SRCC[k]||'#858CB0'}"></i>${k}<span>${Math.round(v/tot*100)}%</span></div>`).join('');
  const d=[41,38,36,33,30,27,25,23.4],W=320,H=120,pl=26,pr=14,pt=14,pb=22,x=i=>pl+i*(W-pl-pr)/7,y=v=>pt+(45-v)/25*(H-pt-pb),p=d.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join(' ');let g='';
  [25,35,45].forEach(v=>{g+=`<line x1="${pl}" x2="${W-pr}" y1="${y(v)}" y2="${y(v)}" class="sv-grid"/><text x="${pl-6}" y="${y(v)+3}" text-anchor="end" font-size="9" class="sv-dim" font-family="IBM Plex Mono,monospace">${v}</text>`});[[0,'W35'],[3,'W38'],[7,'W42']].forEach(([i,t])=>{g+=`<text x="${x(i)}" y="${H-6}" text-anchor="middle" font-size="9" class="sv-dim" font-family="IBM Plex Mono,monospace">${t}</text>`});
  $('#trend').innerHTML=`${g}<path d="${p} L${x(7)} ${H-pb} L${pl} ${H-pb}Z" fill="url(#gArea)"/><path d="${p}" fill="none" stroke="url(#gGrad)" stroke-width="2.5"/><circle cx="${x(7)}" cy="${y(23.4)}" r="4" fill="#EC4899"/><text x="${x(7)-6}" y="${y(23.4)-9}" text-anchor="end" font-size="10" class="sv-txt" font-family="IBM Plex Mono,monospace">23.4d</text>`;
  $('#reqTable').innerHTML=`<table><thead><tr><th>Requisition</th><th>City</th><th class="r">Openings</th><th class="r">In pipeline</th><th class="r">Interview+</th><th>Health</th></tr></thead><tbody>${REQS.map(r=>{const p=POOL.filter(c=>c.req===r.id),iv=p.filter(c=>STG.indexOf(c.stage)>=2).length,hc={good:['var(--good)','On track'],warn:['var(--warn)','Watch'],bad:['var(--bad)','At risk']}[r.health];return`<tr><td><b style="font-weight:600">${r.id}</b> · ${esc(r.role)}</td><td>${esc(r.city)}</td><td class="r">${r.open}</td><td class="r">${p.length}</td><td class="r">${iv}</td><td><span class="health"><i style="background:${hc[0]}"></i>${hc[1]}</span></td></tr>`}).join('')}</tbody></table>`;
  $('#anFeed').innerHTML=FEED.slice(0,16).map(feedHtml).join('')}

/* agents tab */
function renderAgents(){$('#agGrid').innerHTML=AGENTS.map(a=>`<div class="ag-card glass"><div class="top"><span class="av" style="background:${a.c};width:44px;height:44px;border-radius:12px">${a.ic}</span><div><div class="nm">${a.nm}</div><div class="rl">${a.rl}</div></div><span class="pill ok" style="margin-left:auto"><span class="live-dot"></span>Working</span></div><div class="now">› ${esc(a.now)}</div>${spark(a.hist,a.c,300,44)}<div class="ag-stats"><div><b>${a.done}</b><span>tasks today</span></div><div><b>${(a.done*.11).toFixed(1)}h</b><span>time saved</span></div><div><b>${(97+((a.done*7)%25)/10).toFixed(1)}%</b><span>approval rate</span></div></div><div><div class="lbl">Autonomy</div><div class="seg" data-ag="${a.id}">${['suggest','approve','auto'].map(m=>`<button data-m="${m}" class="${a.mode===m?'on':''}">${modeLbl[m]}</button>`).join('')}</div></div></div>`).join('')}
$('#agGrid').onclick=e=>{const b=e.target.closest('.seg button');if(!b)return;const a=AG[b.closest('.seg').dataset.ag];a.mode=b.dataset.m;award('m_autonomy');renderAgents();renderSquad();toast(`${a.nm} set to ${modeLbl[a.mode]}`)};

/* modules + badges */
function renderMods(){const cnt=STG.map(s=>POOL.filter(c=>c.stage===s).length),tot=cnt.reduce((a,b)=>a+b,0);$('#mPipe').textContent=tot;$('#bPipe').textContent=tot;$('#mStack').innerHTML=cnt.map((v,i)=>`<i style="flex:${v};background:${STGC[i]}" title="${STG[i]} ${v}"></i>`).join('');$('#mDots').innerHTML=AGENTS.map(a=>`<span style="background:${a.c}" title="${a.nm}">${a.ic}</span>`).join('');const a=pick(AGENTS);$('#mAgentNow').textContent=`${a.nm}: ${a.now}`;$('#mAppr').textContent=APPROVALS.length;$('#mApprTop').textContent=APPROVALS[0]?APPROVALS[0].x:'All clear'}
renderMods();

/* autopilot */
function bumpStats(k=1){TG.cv+=k;TG.hrs+=Math.random()<.4?1:0;TG.inr+=Math.round(rnd(800,2400)*k/3);if(view==='ws'&&tab==='analytics'){const el=$('#kCv');el.textContent=TG.cv;el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),500);$('#kHrs').textContent=Math.round(TG.hrs/5)}}
function agentAct(){if(tourOn)return;const a=pick(AGENTS);a.hist.push(Math.round(rnd(2,9)));a.hist.shift();a.done++;let msg='';const auto=$('#auto').checked;
  if(a.id==='sourcer'){const r=pick(REQS.slice(0,6));if(POOL.length<220&&auto){const c=mkCand(r,'Sourced');c.ev=[{t:clock(),x:'Sourced from '+c.src+' by Sourcer'}];POOL.push(c);justMoved.add(c.id)}msg=`Found ${Math.round(rnd(12,70))} profiles for ${r.id} · ${r.city}`;a.now=`naukri.search · ${r.role} · ${r.city}`}
  else if(a.id==='screener'){const c=POOL.find(c=>c.stage==='Sourced');if(c&&auto){if(a.mode==='suggest')addApproval('screener',`Move ${c.nm} to Screened (score ${c.sc})`,'Stage');else{moveCand(c,'Screened','Screener');justMoved.add(c.id)}msg=`Scored ${c.nm} ${c.sc} for ${c.req}`}else msg='Scored 6 new applicants';a.now=`score.rank · ${c?c.req:'queue'}`;bumpStats(Math.ceil(rnd(1,5)))}
  else if(a.id==='scheduler'){const c=POOL.find(c=>c.stage==='Screened'&&c.sc>=80);if(c&&auto){if(a.mode!=='auto'){if(Math.random()<.3&&APPROVALS.length<9)addApproval('scheduler',`Book panel for ${c.nm} · ${pick(['Mon','Tue','Wed','Thu','Fri'])} ${pick(['10:00','11:30','15:00'])}`,'Schedule');msg=`Held a slot for ${c.nm}`}else{moveCand(c,'Interview','Scheduler');justMoved.add(c.id);TG.int++;msg=`Booked ${c.nm} · ${pick(['Tue','Wed','Thu'])} ${pick(['11:30','14:00','16:30'])}`}}else msg='Sent 3 interview reminders';a.now='calendar.solve · '+(c?c.nm:'reminders')}
  else{const r=pick(REQS);msg=pick([`Recomputed funnel for ${r.id}`,`Flagged ${r.id}: ${pick(['panel delay','low pipeline','offer risk'])}`,'Synced '+Math.round(rnd(6,30))+' updates to '+atsName()]);a.now='report.refresh · '+r.id;if(Math.random()<.3){syncLog.unshift(['in',`Webhook: new application · ${r.id}`]);renderSync()}}
  pushFeed(a.id,msg);renderMods();if(view==='home')renderSquad();else{if(tab==='pipeline')renderBoard();else if(tab==='agents')renderAgents();else if(tab==='command')renderRail();else if(tab==='analytics')renderAnalytics()}}
setInterval(agentAct,reduce?6000:2700);
$('#auto').onchange=e=>toast(e.target.checked?'Autopilot on: agents act within your guardrails':'Autopilot paused',e.target.checked);

/* guided demo */
let tourOn=false,tourId=0;
function spot(el){$$('.spot').forEach(e=>e.classList.remove('spot'));if(el){el.classList.add('spot');el.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'})}}
function endTour(){tourOn=false;tourId++;$('#tourBox').innerHTML='';spot(null)}
function tourUI(i,n,txt){$('#tourBox').innerHTML=`<div class="tour glass" role="status"><div class="h"><span class="live-dot"></span>Live demo · AJ narrator<span>Step ${i} of ${n}</span></div><p>${txt}</p><div class="bar"><i style="width:${i/n*100}%"></i></div><div class="acts"><button class="btn btn-ghost btn-sm" data-tq>Exit demo</button><button class="btn btn-ghost btn-sm" data-ttry>Skip to try it myself</button></div></div>`;
  $('#tourBox .tour').onclick=e=>{if(e.target.closest('[data-tq]')){endTour();toast('Demo stopped. The workspace is yours.')}if(e.target.closest('[data-ttry]')){endTour();go('sandbox')}};if($('#narrate').checked)speak(txt.replace(/<[^>]+>/g,''))}
async function typeInto(inp,text,id){inp.value='';for(const ch of text){if(id!==tourId)return false;inp.value+=ch;await sleep(reduce?0:28)}return true}
async function startTour(kind='source'){if(busy){toast('Wait for the current task to finish',false);return}endTour();tourOn=true;const id=++tourId;closeOverlay();const first=!go.booted;go('command');const ok=()=>id===tourId;if(first&&!reduce)await sleep(2000);if(!ok())return;
  const bt={source:'Find 8 React developers in Hyderabad, notice under 30 days',report:'Pipeline health report for my hiring manager',risk:'Why is REQ-1987 slow to fill?',schedule:'Schedule panel interviews this week'}[kind]||TASKS.source.label;const N=8;
  const sideEl=innerWidth>980?$('#sidebar'):$('#wsHead');
  tourUI(1,N,'This is the <b>AJ workspace</b>. Everything lives in the <b>left panel</b>: the overview, live demos, Command, Try it, Pipeline, Analytics, Reports, Agents and Approvals.');spot(sideEl);await sleep(4400);if(!ok())return;
  tourUI(2,N,'You brief AJ in plain English, the way you would brief a colleague. Watch it type a real request.');spot($('#composer'));await sleep(1200);if(!ok())return;if(!await typeInto($('#ask'),bt,id))return;await sleep(500);if(!ok())return;$('#ask').value='';
  tourUI(3,N,'AJ makes a plan and runs it. Each line shows <b>which agent</b> did the work and <b>which tool</b> it used, so every step is auditable.');spot(null);await run(bt,kind);if(!ok())return;const d=$('#thread').lastElementChild;spot(d.querySelector('.result'));
  if(kind==='source'){tourUI(4,N,'Here is a ranked shortlist. Every score is explained. Let\'s open the top candidate.');await sleep(3200);if(!ok())return;const tr=d.querySelector('tr[data-c]');if(tr)openCand(tr.dataset.c);tourUI(5,N,'The six-factor radar shows <b>why</b> this person scored as they did, with the agent timeline. Name, gender and age are masked during scoring.');await sleep(5000);if(!ok())return;closeOverlay();d.querySelector('[data-act="push"]')?.click()}
  else{tourUI(4,N,'The result is ready to use: copy it, act on it, or send it on. Nothing is sent without your approval.');await sleep(4500);if(!ok())return;if(kind==='risk')d.querySelector('[data-act="fix"]')?.click();tourUI(5,N,'Suggested actions land in your approval queue rather than running automatically.');await sleep(3000);if(!ok())return}
  go('pipeline');spot($('#board'));tourUI(6,N,'The <b>pipeline board</b> updates as agents work. With Autopilot on, cards move on their own. You can drag them too.');await sleep(4800);if(!ok())return;
  openApprovals();tourUI(7,N,'The <b>approval queue</b> is your control point. Outreach, rejections and bookings wait here until you sign off.');await sleep(4800);if(!ok())return;closeOverlay();
  go('reports');spot($('#doc'));tourUI(8,N,'The Analyst agent writes a <b>full TA report</b> in nine sections. Now it\'s your turn: open <b>Try it yourself</b> and run AJ on your own JD or candidates.');await sleep(5500);if(!ok())return;award('m_tour');endTour();go('sandbox');toast('Your turn. Change the brief and press Run.')}

/* command palette */
const PAL=[...Object.entries(TASKS).map(([k,t])=>({l:t.label,h:'Run task',f:()=>{go('command');run(t.label,k)}})),{l:'Watch the guided demo',h:'Demo',f:()=>startTour('source')},{l:'Try it yourself (sandbox)',h:'Tool',f:()=>go('sandbox')},{l:'Pipeline board',h:'Tool',f:()=>go('pipeline')},{l:'Live analytics',h:'Tool',f:()=>go('analytics')},{l:'TA performance report',h:'Tool',f:()=>go('reports')},{l:'Agent team',h:'Tool',f:()=>go('agents')},{l:'Approval queue',h:'Action',f:()=>openApprovals()},{l:'Toggle Autopilot',h:'Action',f:()=>{$('#auto').checked=!$('#auto').checked;$('#auto').dispatchEvent(new Event('change'))}},{l:'Switch light / dark theme',h:'Action',f:()=>$('#themeBtn').click()},{l:'Overview',h:'Page',f:()=>go('home')},{l:'Impact infographics',h:'Page',f:()=>go('#impact')},{l:'Demos by HR role',h:'Page',f:()=>go('#demo')},{l:'ATS integration',h:'Page',f:()=>go('#ats')},{l:'ROI calculator',h:'Page',f:()=>go('#roi')},{l:'Creator · Ajay Kumar',h:'Page',f:()=>go('#creator')}];
let palSel=0,palList=PAL;
function openPal(){overlayKind='pal';$('#overlay').innerHTML=`<div class="scrim pal-scrim" data-close></div><div class="pal" role="dialog" aria-label="Command palette"><input id="palIn" placeholder="Search tools and pages, or type a brief…" autocomplete="off"><ul id="palUl"></ul></div>`;palSel=0;palList=PAL;drawPal();const i=$('#palIn');i.focus();
  i.oninput=()=>{const q=i.value.toLowerCase();palList=PAL.filter(p=>p.l.toLowerCase().includes(q));if(q&&!palList.length)palList=[{l:`Brief AJ: "${i.value}"`,h:'Run',f:()=>{go('command');run(i.value)}}];palSel=0;drawPal()};
  i.onkeydown=e=>{if(e.key==='ArrowDown'){palSel=Math.min(palList.length-1,palSel+1);drawPal();e.preventDefault()}if(e.key==='ArrowUp'){palSel=Math.max(0,palSel-1);drawPal();e.preventDefault()}if(e.key==='Enter'&&palList[palSel]){const f=palList[palSel].f;closeOverlay();f()}};
  $('#palUl').onclick=e=>{const l=e.target.closest('li');if(l){const f=palList[+l.dataset.i].f;closeOverlay();f()}}}
