function renderXP(){const x=xpTotal(),{l,n}=lvlOf(x);$('#xpLvl').textContent=l[2];$('#xpNum').textContent=x+' XP';$('#bXp').textContent=x+' XP';$('#xpBar').style.width=(n?(x-l[0])/(n[0]-l[0])*100:100)+'%'}
