function md(t){const lines=esc(t).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').split(/\n/);let h='',ul=false;for(const l of lines){const m=l.match(/^\s*(?:[-•*]|\d+\.)\s+(.*)/);if(m){if(!ul){h+='<ul>';ul=true}h+=`<li>${m[1]}</li>`}else{if(ul){h+='</ul>';ul=false}if(l.trim())h+=`<p>${l.replace(/^#+\s*/,'')}</p>`}}if(ul)h+='</ul>';return h}
function pipeCtx(){return JSON.stringify({open_reqs:REQS.slice(0,6).map(r=>({id:r.id,role:r.role,city:r.city,openings:r.open,health:r.health})),pipeline:Object.fromEntries(STG.map(s=>[s,POOL.filter(c=>c.stage===s).length])),time_to_fill_days:23.4,offer_acceptance:'82%',top_risk:'REQ-1987 Staff SRE Noida has a thin pipeline; REQ-2104 Salesforce Architect Pune offer is 18% below market'})}
const AI_OFF=['not_granted','sampling_disabled','capability_disabled','capability_removed','not_declared','session_expired'];
function aiFail(e,el,keep){const code=e&&e.code;if(AI_OFF.includes(code)){AI.avail=false;AI.on=false;$('#aiPill').hidden=true;$('#aiChip')?.remove();el.innerHTML=(keep||'')+'<p>Live AI is not available in this view, so AJ is using the built-in demo. Try one of the tasks above.</p>'}
  else if(code==='rate_limited'||code==='queue_overflow'){el.innerHTML=(keep||'')+'<p>Live AI is busy right now. Wait a minute and try again.</p>'}
  else el.innerHTML=(e&&e.text?md(e.text):(keep||''))+'<p style="color:var(--dim)">The answer stopped early. Ask again to retry.</p>'}
async function aiAsk(text){if(busy){toast('AJ is finishing the current task',false);return}busy=true;
  add(`<div class="bubble">${esc(text)}</div>`,'user');const m=add(head()+`<div class="bubble ai-ans"><span class="ai-badge">✦ Live AI</span> Thinking<span class="thinking"><i></i><i></i><i></i></span></div>`,'agent');const b=m.querySelector('.bubble');const badge='<span class="ai-badge">✦ Live AI</span>';
  const prompt=`You are AJ, a Smart Hiring Agent built for recruiters and HR teams in India. Answer the recruiter's question.\n\nRules:\n- Plain, direct business English. No hype, no emojis.\n- Under 170 words. Use short "- " bullets for steps or options.\n- If the question needs live data you do not have, say what you would check and still give practical guidance.\n- You may draw on this sample pipeline context: ${pipeCtx()}\n\nQuestion: ${text}`;
  try{const r=await AI.fn(prompt,{modelTier:'quick',onText:({text:t})=>{b.innerHTML=badge+md(t)}});b.innerHTML=badge+md(r.text);award('m_ai');addDL(m,{title:'Live AI answer',sub:'Question: '+text});pushFeed('analyst','Answered an open question with Live AI')}
  catch(e){aiFail(e,b,badge)}finally{busy=false}}
async function aiJD(d,req){const dr=d.querySelector('.draft');if(!dr)return;const orig=dr.textContent;dr.textContent='Writing with Live AI…';d.querySelector('h4').insertAdjacentHTML('beforeend',' <span class="ai-badge">✦ Live AI</span>');
  const prompt=`Write a job description for a ${req.role} based in ${req.city}, India, for an IT services company. Core skills: ${req.skills.join(', ')}.\nFormat as plain text with these headings on their own lines: About the role, What you'll do (5 bullets starting with "- "), What you bring (5 bullets), Nice to have (3 bullets), Location and work mode.\nUse inclusive, plain language. Under 260 words. No salary figures. No markdown symbols other than "- " for bullets.`;
  try{const r=await AI.fn(prompt,{modelTier:'quick',onText:({text:t})=>{dr.textContent=t}});dr.textContent=r.text;award('m_ai')}catch(e){if(AI_OFF.includes(e&&e.code)){AI.avail=false;AI.on=false;$('#aiPill').hidden=true;$('#aiChip')?.remove()}dr.textContent=(e&&e.text)||orig}}
async function aiOutreach(c){const box=$('#dDraft');if(!box)return;box.innerHTML='<div class="draft">Writing with Live AI…</div>';const dr=box.firstChild;
  const prompt=`Write a short recruiting message (WhatsApp or email) to ${c.nm.split(' ')[0]}, a candidate with ${c.exp} years of experience in ${c.sk.join(', ')}, for a ${c.role} role in ${c.city}, India. Be warm and specific to their skills, mention one reason the role fits them, and end with a simple question asking for a 15-minute call this week. Under 90 words. Plain text only, no subject line, sign off as "Talent Acquisition team".`;
  try{const r=await AI.fn(prompt,{modelTier:'quick',onText:({text:t})=>{dr.textContent=t}});dr.textContent=r.text;box.insertAdjacentHTML('beforeend','<div class="res-actions" style="margin-top:8px"><button class="btn btn-primary btn-sm" data-queue>Send for approval</button></div>');award('m_ai')}
  catch(e){if(AI_OFF.includes(e&&e.code)){AI.avail=false;AI.on=false;$('#aiPill').hidden=true;$('#aiChip')?.remove()}dr.textContent=(e&&e.text)||outreach(c)}}

