(function(){const st=$('#flowStage'),cv=$('#flowCv');if(!st||!cv)return;const x=cv.getContext('2d');let W=0,H=0,ins=[],outs=[],core={x:0,y:0},P=[],vis=true,last=0,spawnT=0,raf=0;
  function layout(){const r=st.getBoundingClientRect();if(!r.width)return;const d=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*d;cv.height=H*d;x.setTransform(d,0,0,d,0,0);
    const rel=el=>{const b=el.getBoundingClientRect();return{x:b.left-r.left,y:b.top-r.top,w:b.width,h:b.height}};
    ins=$$('#fsIn .fs-chip').map(el=>{const b=rel(el);return{x:b.x+b.w+2,y:b.y+b.h/2,c:el.dataset.c}});
    outs=$$('#fsOut .fs-chip').map(el=>{const b=rel(el);return{x:b.x-2,y:b.y+b.h/2,c:el.dataset.c,el,v:+el.dataset.v}});
    const o=rel($('#flowStage .fs-core'));core={x:o.x+o.w/2,y:o.y+o.h/2};if(reduce)rails()}
  const bez=(a,b,c,t)=>{const u=1-t;return{x:u*u*a.x+2*u*t*b.x+t*t*c.x,y:u*u*a.y+2*u*t*b.y+t*t*c.y}};
  function rails(){x.clearRect(0,0,W,H);x.lineWidth=1.2;x.setLineDash([3,6]);ins.forEach(s=>{x.strokeStyle=s.c+'66';x.beginPath();x.moveTo(s.x,s.y);x.quadraticCurveTo((s.x+core.x)/2,s.y,core.x,core.y);x.stroke()});outs.forEach(o=>{x.strokeStyle=o.c+'66';x.beginPath();x.moveTo(core.x,core.y);x.quadraticCurveTo((core.x+o.x)/2,o.y,o.x,o.y);x.stroke()});x.setLineDash([])}
  function spawnIn(){const s=pick(ins);if(s)P.push({a:s,b:{x:(s.x+core.x)/2,y:s.y},c:core,t:0,v:rnd(.006,.011),col:s.c,dir:1})}
  function spawnOut(){const w=[.56,.27,.11,.06];let r=Math.random(),i=0;while(i<3&&r>w[i]){r-=w[i];i++}const o=outs[i];if(o)P.push({a:core,b:{x:(core.x+o.x)/2,y:o.y},c:o,t:0,v:rnd(.007,.012),col:o.c,dir:2,o})}
  function frame(ts){if(!vis||document.hidden||!W){raf=0;return}const dt=Math.min(50,ts-(last||ts));last=ts;rails();spawnT+=dt;if(spawnT>130){spawnT=0;spawnIn()}
    for(let i=P.length-1;i>=0;i--){const p=P[i];p.t+=p.v*dt/16;if(p.t>=1){P.splice(i,1);if(p.dir===1){if(Math.random()<.42)spawnOut()}else{p.o.v++;const b=p.o.el.querySelector('b');if(b)b.textContent=p.o.v.toLocaleString('en-IN');p.o.el.classList.add('pulse');setTimeout(()=>p.o.el.classList.remove('pulse'),220)}continue}
      const q=bez(p.a,p.b,p.c,p.t),q2=bez(p.a,p.b,p.c,Math.max(0,p.t-.07));const g=x.createLinearGradient(q2.x,q2.y,q.x,q.y);g.addColorStop(0,p.col+'00');g.addColorStop(1,p.col);x.strokeStyle=g;x.lineWidth=2.6;x.lineCap='round';x.beginPath();x.moveTo(q2.x,q2.y);x.lineTo(q.x,q.y);x.stroke();x.fillStyle=p.col;x.beginPath();x.arc(q.x,q.y,2.8,0,7);x.fill()}
    raf=requestAnimationFrame(frame)}
  const start=()=>{if(!raf&&!reduce){last=0;raf=requestAnimationFrame(frame)}};
  layout();if(window.ResizeObserver)new ResizeObserver(()=>{layout();start()}).observe(st);addEventListener('resize',layout);
  new IntersectionObserver(es=>{vis=es[0].isIntersecting;if(vis){layout();start()}}).observe(st);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)start()});start();
  setInterval(()=>{$('#fsRate').textContent=Math.round(rnd(36,58))},2200)})();

