const AU={i:0,run:0,on:[true,true,true]};
function renderAuList(){$('#auList').innerHTML=RECIPES.map((r,i)=>`<button type="button" class="au-rec ${i===AU.i?'on':''}" data-i="${i}"><span class="tr">⚡ ${esc(r.tr)}</span><b>${esc(r.name)}</b><small>${r.runs} · ${AU.on[i]?'Active':'Paused'}</small></button>`).join('')}
function renderAu(){const r=RECIPES[AU.i];$('#auMain').innerHTML=`<div class="au-top"><div><div class="lbl" style="margin:0">Trigger</div><h3>${esc(r.tr)}</h3></div><div class="right"><label class="sw" for="auOn"><input type="checkbox" id="auOn" ${AU.on[AU.i]?'checked':''}> Active</label><button class="btn btn-primary btn-sm" id="auTest" type="button">▶ Test run</button></div></div>
  <div class="au-chain" id="auChain">${r.steps.map(([ic,cls,t,d,ag],k)=>`<div class="au-step ${cls}" data-k="${k}"><span class="au-ic"><svg viewBox="0 0 24 24">${AUI[ic]}</svg></span><div class="au-body"><b>${esc(t)}</b><small>${esc(d)}</small></div><div class="au-meta">${agB(ag)}<span class="au-st">${k?'—':'trigger'}</span></div></div>`).join('')}</div>
  <div class="au-res" id="auRes">Runs ${r.runs}, ${r.save}. Press <b>Test run</b> to watch it fire.</div>`}
async function auTest(){const id=++AU.run,r=RECIPES[AU.i],steps=$$('#auChain .au-step');const b=$('#auTest');b.disabled=true;b.textContent='Running…';let tot=0;
  for(let k=0;k<steps.length;k++){if(id!==AU.run)return;const el=steps[k];el.classList.add('run');const t=rnd(.18,.55);await sleep(reduce?40:t*1400);if(id!==AU.run)return;tot+=t;el.classList.remove('run');el.classList.add('done');el.querySelector('.au-st').textContent=k?t.toFixed(2)+'s':'fired'}
  $('#auRes').innerHTML=`<b class="gt">Completed in ${tot.toFixed(1)}s</b> with 0 manual clicks. By hand this takes about ${r.manual}. ${AU.on[AU.i]?'This recipe is active.':'Switch it on to run it for real.'}`+`<div class="res-actions" style="margin-top:8px">${dlBtns('auto')}</div>`;b.disabled=false;b.textContent='▶ Run again';award('m_auto');pushFeed('tara',`Automation tested · ${r.name}`)}
