const ACTIONS=[];const DLB={};let dlN=0;
const dlBtns=id=>`<span class="dl-grp"><button type="button" class="btn btn-ghost btn-sm dl" data-dl="${id}" data-f="pdf">⬇ PDF</button><button type="button" class="btn btn-ghost btn-sm dl" data-dl="${id}" data-f="csv">⬇ CSV</button></span>`;
function logAction(title){ACTIONS.unshift({t:clock(),title});if(ACTIONS.length>200)ACTIONS.pop()}
function scrape(el,o){o=o||{};const rep={title:o.title||(el.querySelector('h4,h3')?.textContent.trim())||'AJ action',sub:o.sub||'',kpis:[],text:[],steps:[],tables:[]};
  el.querySelectorAll('.tile').forEach(t=>rep.kpis.push([t.querySelector('.l')?.textContent.trim()||'',t.querySelector('.n')?.textContent.trim()||'']));
  el.querySelectorAll('.draft,.ai-ans').forEach(d=>rep.text.push(d.innerText||d.textContent));
  el.querySelectorAll('p.c,.verdict,.au-res').forEach(p=>rep.text.push(p.textContent.trim()));
  const st=o.stepsFrom||el.previousElementSibling;if(st)st.querySelectorAll('.log>div').forEach(r=>{const a=r.querySelector('.ag')?.textContent||'',tool=r.querySelector('.tool')?.textContent||'',tx=r.querySelector('.txt')?.textContent||'';if(tool)rep.steps.push([a,tool,tx])});
  el.querySelectorAll('table').forEach(t=>rep.tables.push(tblFrom(t,'')));
  if(!rep.text.length&&!rep.tables.length){const b=el.querySelector('.bubble');if(b)rep.text.push(b.innerText||b.textContent)}
  return rep}
function addDL(el,o){if(!el)return;const id='a'+(++dlN);DLB[id]=()=>scrape(el,o);logAction(o&&o.title||el.querySelector('h4,h3')?.textContent||'Action');let ra=[...el.querySelectorAll('.res-actions')].pop();if(!ra){ra=document.createElement('div');ra.className='res-actions';(el.querySelector('.result')||el).appendChild(ra)}ra.insertAdjacentHTML('beforeend',dlBtns(id))}
