function candRep(id){const c=byId(id);if(!c)return null;return{title:`Candidate scorecard · ${c.nm}`,sub:`${c.role} · ${c.req} · ${c.city} · stage ${c.stage}`,kpis:[['Match score',String(c.sc)],['Experience',c.exp+' yrs'],['Notice',c.np?c.np+' days':'Immediate'],['Expected CTC','Rs '+c.ctc+' LPA']],text:(c.why||[]).concat(c.miss&&c.miss.length?['Missing: '+c.miss.join(', ')]:[]),steps:[],tables:[{title:'Six-factor breakdown (name, gender and age masked)',cols:['Factor','Score'],rows:AXES.map((a,i)=>[a,String(c.br[i])])},{title:'Skills',cols:['Skill','Status'],rows:c.sk.map(s=>[s,'Matched']).concat((c.miss||[]).map(s=>[s,'Missing']))},{title:'Agent timeline',cols:['Time','Event'],rows:c.ev.map(e=>[e.t,e.x])}]}}
function buildRep(id){if(DLB[id])return DLB[id]();if(id.startsWith('cand:'))return candRep(id.slice(5));return NAMED[id]?NAMED[id]():null}
let pdfP=null;
function ensurePDF(){if(window.jspdf&&window.jspdf.jsPDF&&window.jspdf.jsPDF.API&&window.jspdf.jsPDF.API.autoTable)return Promise.resolve(true);if(pdfP)return pdfP;
  pdfP=Promise.all([import('jspdf'),import('jspdf-autotable')]).then(([m,at])=>{at.applyPlugin(m.jsPDF);window.jspdf={jsPDF:m.jsPDF};return!!m.jsPDF.API.autoTable}).catch(()=>{pdfP=null;return false});return pdfP}
async function saveFile(name,data){const dl=await cap('downloads');if(dl){try{await dl.save({filename:name,data});toast('Saved '+name);award('m_dl');return}catch(e){const c=e&&e.code;if(c==='declined'){toast('Download cancelled',false);return}if(c==='rate_limited'){toast('A download prompt is already open',false);return}if(!['unavailable','not_granted','capability_disabled','capability_removed'].includes(c)){toast('This file could not be saved here',false);return}}}
  try{const type=name.endsWith('.pdf')?'application/pdf':name.endsWith('.csv')?'text/csv;charset=utf-8':'text/html';const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('Downloading '+name);award('m_dl')}catch(e){toast('Downloads are blocked in this view',false)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-dl]');if(!b)return;e.preventDefault();const f=b.dataset.f||'pdf';let rep=null;try{rep=buildRep(b.dataset.dl)}catch(err){}
  if(!rep){toast('Nothing to export yet',false);return}const base=slugF(rep.title)+'-'+stampF();
  if(f==='csv'){saveFile(base+'.csv',makeCSV(rep));return}
  const lbl=b.innerHTML;b.disabled=true;b.textContent='Preparing…';const ok=await ensurePDF();b.disabled=false;b.innerHTML=lbl;
  if(ok){try{saveFile(base+'.pdf',makePDF(rep));return}catch(err){}}saveFile(base+'.html',makeHTML(rep))});

/* ---- ATS capabilities, hub and console ---- */
const mCls=m=>m==='GET'?'m-get':m==='PATCH'?'m-patch':m==='HOOK'?'m-hook':'m-post';
const ATSLOG=[],ATCST=Array(ATSCAP.length).fill(null);let atcBusy=false,atcRate=982;
$('#capGrid').innerHTML=ATSCAP.map((c,i)=>`<button type="button" class="capc2" data-cap="${i}"><span class="m ${mCls(c[2])}">${c[2]}</span><span><b>${c[0]}</b><small>${c[1]}</small></span></button>`).join('');
$('#capGrid').onclick=e=>{const b=e.target.closest('[data-cap]');if(!b)return;go('atscon');setTimeout(()=>atcCall(+b.dataset.cap),go.booted?120:1900)};
function renderHub(){const svg=$('#hubSvg');if(!svg)return;const cx=300,cy=300,R=232,n=ATS.length;let g='';
  ATS.forEach((a,i)=>{const ang=-Math.PI/2+i/n*Math.PI*2,x=cx+Math.cos(ang)*R,y=cy+Math.sin(ang)*R;g+=`<line class="hub-l" x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;
    if(!reduce)g+=`<circle r="3.2" fill="${i%2?'#EC4899':'#2F86F6'}"><animateMotion dur="${(2.4+i%5*.35).toFixed(2)}s" repeatCount="indefinite" begin="-${(i*.37).toFixed(2)}s" path="M${cx},${cy} L${x.toFixed(1)},${y.toFixed(1)}"/></circle>`});
  ATS.forEach((a,i)=>{const ang=-Math.PI/2+i/n*Math.PI*2,x=cx+Math.cos(ang)*R,y=cy+Math.sin(ang)*R,w=Math.max(70,a[0].length*6.6+18);g+=`<g class="hub-n ${i===atsSel?'on':''}" data-i="${i}" tabindex="0" role="button" aria-label="Connect ${esc(a[0])}"><rect x="${(x-w/2).toFixed(1)}" y="${(y-14).toFixed(1)}" width="${w.toFixed(1)}" height="28" rx="14"/><text x="${x.toFixed(1)}" y="${(y+4).toFixed(1)}" text-anchor="middle">${esc(a[0])}</text></g>`});
  g+=`<circle cx="${cx}" cy="${cy}" r="92" fill="none" stroke="#8EC9FF" stroke-opacity=".5" stroke-dasharray="2 6"/><circle cx="${cx}" cy="${cy}" r="120" fill="none" stroke="#FFB3D9" stroke-opacity=".45" stroke-dasharray="40 14"/>`;svg.innerHTML=g}
window.__hub=renderHub;renderHub();
$('#hubSvg').addEventListener('click',e=>{const n=e.target.closest('.hub-n');if(!n)return;atsSel=+n.dataset.i;syncLog.unshift(['in',`Connected to ${atsName()} · fields mapped`]);renderAts();toast(`Connected to ${atsName()} (sample connection)`)});
$('#hubSvg').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const n=e.target.closest('.hub-n');if(n){e.preventDefault();n.dispatchEvent(new MouseEvent('click',{bubbles:true}))}}});
function renderAtc(){$('#atcName').textContent=atsName();$('#atcRate').textContent=atcRate;$('#atcCaps').innerHTML=ATSCAP.map((c,i)=>{const st=ATCST[i];return`<button type="button" class="atc-cap ${st==='run'?'run':st?'ok':''}" data-i="${i}"><div class="h"><span class="m ${mCls(c[2])}" style="font-family:var(--f-mono);font-size:.58rem;font-weight:600;padding:2px 5px;border-radius:4px">${c[2]}</span><b>${c[0]}</b><span class="s">${st==='run'?'running…':st?'✓ '+st:'ready'}</span></div><code>${esc(c[3])}</code><small style="color:var(--muted);font-size:.76rem">${c[1]}</small></button>`}).join('')}
function atcEntry(a){const L=$('#atcLog');if(L.firstElementChild&&!L.firstElementChild.querySelector('.ah'))L.innerHTML='';const el=document.createElement('div');el.className='ae'+(a.dir==='in'?' in':'');el.innerHTML=`<div class="ah"><span class="m ${mCls(a.m)}">${a.dir==='in'?'IN':a.m}</span><code></code><span class="st">${a.code} · ${a.ms} ms</span><time>${a.t}</time></div><pre></pre>`;el.querySelector('code').textContent=a.ep;el.querySelector('pre').textContent=a.body;L.prepend(el);while(L.children.length>30)L.lastChild.remove();$('#atcCount').textContent=ATSLOG.length+' calls'}
async function atcCall(i,quiet){const c=ATSCAP[i];ATCST[i]='run';if(view==='ws'&&tab==='atscon')renderAtc();await sleep(reduce?40:rnd(260,720));const ms=Math.round(rnd(90,460)),body=JSON.stringify({ok:true,ats:atsName().toLowerCase().replace(/\s+/g,'_'),...c[5]()},null,1);
  const a={t:clock(),dir:'out',m:c[2],ep:c[3],code:c[2]==='POST'?201:200,ms,body,cap:c[0]};ATSLOG.unshift(a);if(ATSLOG.length>300)ATSLOG.pop();ATCST[i]=ms+' ms';atcRate=Math.max(900,atcRate-1);
  if(view==='ws'&&tab==='atscon'){renderAtc();atcEntry(a);$('#atcLast').textContent=clock()}syncLog.unshift([c[2]==='GET'?'in':'out',`${c[0]} · ${a.code} in ${ms} ms`]);renderSync();if(!quiet){pushFeed(c[4],`ATS ${c[0]} · ${a.code}`);logAction(`ATS Console: ${c[0]}`)}return a}
$('#atcCaps').onclick=e=>{const b=e.target.closest('.atc-cap');if(b)atcCall(+b.dataset.i)};
$('#atcSync').onclick=async()=>{if(atcBusy)return;atcBusy=true;const b=$('#atcSync');b.disabled=true;b.textContent='Syncing…';for(let i=0;i<ATSCAP.length;i++){await atcCall(i,true);$('#atcProg').style.width=((i+1)/ATSCAP.length*100)+'%'}
  b.disabled=false;b.textContent='▶ Run full sync again';atcBusy=false;toast(`Full sync with ${atsName()} complete · ${ATSCAP.length} capabilities`);pushFeed('tara',`Full ATS sync with ${atsName()} · 16 of 16 OK`);logAction(`ATS full sync with ${atsName()}`);award('m_ats');setTimeout(()=>{$('#atcProg').style.width='0'},1500)};
const HOOKS=[['application.created','screener',()=>({candidate:'C-'+Math.round(rnd(88000,89999)),requisition:pick(REQS).id,source:pick(SRC)})],['candidate.replied','sourcer',()=>({candidate:nm(),channel:pick(['whatsapp','email']),intent:'interested'})],['interview.feedback_submitted','scheduler',()=>({interview:'INT-'+Math.round(rnd(7000,7999)),overall:pick(['yes','strong_yes','no'])})],['offer.accepted','analyst',()=>({offer:'OF-'+Math.round(rnd(2200,2299)),joining:'2026-11-'+pad(Math.round(rnd(3,24)))})]];
setInterval(()=>{if(view!=='ws'||tab!=='atscon'||!$('#atcHook').checked||document.hidden)return;const h=pick(HOOKS),a={t:clock(),dir:'in',m:'HOOK',ep:h[0],code:200,ms:Math.round(rnd(40,180)),body:JSON.stringify(h[2](),null,1),cap:'Webhook'};ATSLOG.unshift(a);atcEntry(a);pushFeed(h[1],`Webhook ${h[0]}`)},3200);

/* ---- live hiring map (India) ---- */
const LM={total:LMC.reduce((s,c)=>s+c.n,0),ev:[],pulses:[],arcs:[],rate:0,times:[]};
const inPoly=(x,y)=>{let c=false;for(let i=0,j=IND.length-1;i<IND.length;j=i++){const [xi,yi]=IND[i],[xj,yj]=IND[j];if(((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))c=!c}return c};
const LMDOTS=[];for(let la=8;la<=36;la+=.62)for(let lo=68;lo<=97.5;lo+=.62)if(inPoly(lo,la))LMDOTS.push([lo,la]);
(function(){const cv=$('#lmCv'),box=$('#lmMap');if(!cv)return;const x=cv.getContext('2d');let W=0,H=0,proj=null,vis=true,raf=0,last=0;
  function layout(){const r=box.getBoundingClientRect();if(!r.width)return;const d=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*d;cv.height=H*d;x.setTransform(d,0,0,d,0,0);const pad2=34,top=50,sx=(W-2*pad2)/(97.5-68),sy=(H-top-pad2)/(36-8),s=Math.min(sx,sy),ox=(W-(97.5-68)*s)/2,oy=top+((H-top-pad2)-(36-8)*s)/2;proj=(lo,la)=>[ox+(lo-68)*s,oy+(36-la)*s];draw(0)}
  function draw(dt){if(!proj)return;x.clearRect(0,0,W,H);const dark=root.getAttribute('data-theme')==='dark';x.fillStyle=dark?'rgba(169,214,255,.22)':'rgba(47,134,246,.22)';LMDOTS.forEach(([lo,la])=>{const [px,py]=proj(lo,la);x.beginPath();x.arc(px,py,1.5,0,7);x.fill()});
    LM.arcs=LM.arcs.filter(a=>(a.t+=dt/1300)<1);LM.arcs.forEach(a=>{const [x1,y1]=proj(a.a.lon,a.a.lat),[x2,y2]=proj(a.b.lon,a.b.lat),mx=(x1+x2)/2,my=Math.min(y1,y2)-60;x.strokeStyle=`rgba(236,72,153,${.55*(1-a.t)})`;x.lineWidth=1.6;x.beginPath();x.moveTo(x1,y1);x.quadraticCurveTo(mx,my,x2,y2);x.stroke();const u=a.t,qx=(1-u)*(1-u)*x1+2*(1-u)*u*mx+u*u*x2,qy=(1-u)*(1-u)*y1+2*(1-u)*u*my+u*u*y2;x.fillStyle='#EC4899';x.beginPath();x.arc(qx,qy,3,0,7);x.fill()});
    LM.pulses=LM.pulses.filter(p=>(p.t+=dt/1500)<1);LM.pulses.forEach(p=>{const [px,py]=proj(p.c.lon,p.c.lat);x.strokeStyle=p.col+Math.round((1-p.t)*200).toString(16).padStart(2,'0');x.lineWidth=2;x.beginPath();x.arc(px,py,6+p.t*26,0,7);x.stroke()});
    const mx=Math.max(...LMC.map(c=>c.n));LMC.forEach(c=>{const [px,py]=proj(c.lon,c.lat),r=4+c.n/mx*6;const g=x.createRadialGradient(px,py,0,px,py,r*2.4);g.addColorStop(0,'rgba(236,72,153,.35)');g.addColorStop(1,'rgba(236,72,153,0)');x.fillStyle=g;x.beginPath();x.arc(px,py,r*2.4,0,7);x.fill();x.fillStyle='#2B7BEF';x.beginPath();x.arc(px,py,r,0,7);x.fill();x.fillStyle='#fff';x.beginPath();x.arc(px,py,r*.42,0,7);x.fill();
      if(c.w>=3||W>520){x.font='600 11px "IBM Plex Sans",sans-serif';x.fillStyle=dark?'#EEF0FF':'#16203F';if(c.side==='l'){x.textAlign='right';x.fillText(c.name,px-r-5,py+4)}else if(c.side==='b'){x.textAlign='center';x.fillText(c.name,px,py+r+14)}else{x.textAlign='left';x.fillText(c.name,px+r+5,py+4)}x.textAlign='left'}})}
  function frame(ts){if(!vis||document.hidden||!W){raf=0;return}const dt=Math.min(60,ts-(last||ts));last=ts;draw(dt);raf=requestAnimationFrame(frame)}
  const start=()=>{if(!raf&&!reduce){last=0;raf=requestAnimationFrame(frame)}};
  layout();if(window.ResizeObserver)new ResizeObserver(layout).observe(box);new IntersectionObserver(es=>{vis=es[0].isIntersecting;if(vis){layout();start()}}).observe(box);
  function event(){const tot=LMC.reduce((s,c)=>s+c.w,0);let r=Math.random()*tot,c=LMC[0];for(const k of LMC){r-=k.w;if(r<=0){c=k;break}}const ti=Math.min(4,Math.floor(Math.pow(Math.random(),1.8)*5)),type=LMT[ti];c.n++;LM.total++;const role=pick(REQS.slice(0,6)).role;
    LM.ev.unshift({t:clock(),city:c.name,type,role});if(LM.ev.length>40)LM.ev.pop();LM.pulses.push({c,t:0,col:LMTC[ti]});if(Math.random()<.25){const b=pick(LMC.filter(k=>k!==c));LM.arcs.push({a:c,b,t:0})}LM.times.push(Date.now());
    if(!vis)return;const f=$('#lmFeed');const el=document.createElement('div');el.className='lm-ev';el.innerHTML=`<i style="background:${LMTC[ti]}"></i><span></span><time>${clock()}</time>`;el.querySelector('span').textContent=`${c.name} · ${type} · ${role}`;f.prepend(el);while(f.children.length>7)f.lastChild.remove();renderLmTop();if(reduce)draw(0)}
  function renderLmTop(){const s=LMC.slice().sort((a,b)=>b.n-a.n).slice(0,6),mx=s[0].n;$('#lmTop').innerHTML=s.map((c,i)=>`<div class="lm-c"><span class="rk">${pad(i+1)}</span><span>${c.name}</span><span class="tr"><i style="width:${c.n/mx*100}%"></i></span><span class="v">${c.n}</span></div>`).join('');$('#lmTotal').textContent=LM.total.toLocaleString('en-IN');const now=Date.now();LM.times=LM.times.filter(t=>now-t<60000);$('#lmRate').textContent=LM.times.length}
  for(let i=0;i<6;i++)event();renderLmTop();setInterval(event,reduce?3000:1100);start()})();

