(function(){const btn=$('#robotBtn'),eyes=$('#rbEyes'),say=$('#rbSay');if(!btn)return;
  addEventListener('pointermove',e=>{if($('#landing').hidden)return;const r=btn.getBoundingClientRect();if(!r.width)return;const cx=r.left+r.width/2,cy=r.top+r.height*.4,dx=e.clientX-cx,dy=e.clientY-cy,d=Math.hypot(dx,dy)||1,k=Math.min(7,d/45);eyes.setAttribute('transform',`translate(${(dx/d*k).toFixed(1)} ${(dy/d*k*.7).toFixed(1)})`)},{passive:true});
  const LINES=["Hi, I'm AJ.","Brief me like a colleague.","Screening 24 CVs…","63 duplicates merged.","9 interviews booked.","Your approval needed ✋","Synced to "+atsName()+" ✓","Click me to start."];let li=0,tm=null;
  function type(t){clearInterval(tm);let i=0;say.textContent='';if(reduce){say.textContent=t;return}tm=setInterval(()=>{say.textContent=t.slice(0,++i);if(i>=t.length)clearInterval(tm)},38)}
  type(LINES[0]);setInterval(()=>{if($('#landing').hidden||document.hidden)return;li=(li+1)%LINES.length;type(LINES[li].replace(/Synced to .*? ✓/,'Synced to '+atsName()+' ✓'))},3200);
  btn.addEventListener('mouseenter',()=>type('Ready when you are. Click to enter.'))})();

