$('#sbMini').onclick=()=>setMini(!document.body.classList.contains('sb-mini'));
try{if(localStorage.getItem('shubh-mini')==='1')setMini(true)}catch(e){}
$$('.sidebar .sb-item').forEach(b=>{if(!b.title)b.title=[...b.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim()});

/* ---------- sparkles ---------- */
$$('.sparkle').forEach(el=>{[[18,22],[70,18],[44,72]].forEach(([l,t])=>{const s=document.createElement('span');s.className='tw';s.style.left=l+'%';s.style.top=t+'%';el.appendChild(s)})});

/* ---------- access (gate runs in its own script) ---------- */
async function cap(n){try{return window.claude&&window.claude.use?await window.claude.use(n):null}catch(e){return null}}
function openGate(){if(window.shubhGate)window.shubhGate.open()}
/* owner-only access list */
let LEADS=[],leadsSub=null,LUSER=null,LEADROWS=[];
(async()=>{const user=await cap('user');if(!user)return;LUSER=user;let owner=false;try{owner=await user.isOwner()}catch(e){}if(!owner)return;const db=await cap('db');if(!db)return;
  $('#sbLeads').hidden=false;
  leadsSub=db.collection('visitors').orderBy('at','desc').onSnapshot(s=>{LEADS=s.docs.map(d=>Object.assign({},d.data(),{_id:d.id})).filter(v=>v&&v.at);$('#bLeads').textContent=LEADS.length;if(overlayKind==='leads')openLeads()},()=>{})})();
async function openLeads(){let ps={};try{if(LUSER&&LEADS.length)ps=await LUSER.profiles(LEADS.map(v=>v._id))}catch(e){}
  const rows=LEADS.map(v=>{const pr=ps[v._id]||{};return{email:v.email||pr.email||'',name:pr.name||v.name||'',via:v.via==='account'?'Signed-in account':'Typed email',at:v.at}});LEADROWS=rows;
  drawer(`<div><span class="cat"><b>Owner</b><i></i>Access list</span><h3 style="margin-top:8px">${rows.length} ${rows.length===1?'person has':'people have'} opened AJ</h3><p style="color:var(--muted);font-size:.86rem;margin-top:4px">Saved when a signed-in viewer enters. Only you see this list.</p></div>
  <div class="res-actions">${rows.some(r=>r.email)?'<button class="btn btn-primary btn-sm" data-copyall>Copy all emails</button>':''}${dlBtns('leads')}</div>
  <div class="leads" id="leadsBox">${rows.length?'':'<div class="empty"><b>No one yet</b>Share this page from its Share menu. Each viewer enters before they see the agent, and appears here.</div>'}</div>`,'leads');
  const box=$('#leadsBox');rows.forEach(r=>{const el=document.createElement('div');el.className='lead';const label=r.name||r.email||'Viewer';el.innerHTML=`<span class="av"></span><div><b style="font-weight:600"></b><small></small></div><time></time>`;el.querySelector('.av').textContent=(label.split(/[\s@.]/).filter(Boolean).map(w=>w[0]).join('').slice(0,2)||'?').toUpperCase();el.querySelector('b').textContent=r.email||r.name||'Signed-in viewer';el.querySelector('small').textContent=[r.email?r.name:'',r.via].filter(Boolean).join(' · ');el.querySelector('time').textContent=r.at?new Date(r.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'';box.appendChild(el)});
  $('.drawer').onclick=e=>{if(e.target.closest('[data-copyall]'))copyText(rows.filter(r=>r.email).map(r=>r.email).join(', '),rows.filter(r=>r.email).length+' emails copied')}}
document.addEventListener('click',e=>{if(e.target.closest('[data-act="leads"]')){closeNav();openLeads()}});

const h=location.hash.slice(1);if(['command','sandbox','pipeline','analytics','reports','agents'].includes(h))go(h);else if(h==='demo-live')startTour('source');
